const handleDelete = async (id) => {
    if (!window.confirm("Delete this master item?")) return;
    try {
        const savedUser = localStorage.getItem('user');
        const { token } = JSON.parse(savedUser);
        await fetchWithAuth(`${import.meta.env.VITE_API_URL}/products/${id}`, {
            method: 'DELETE'
        });
        fetchData();
    } catch (err) { console.error(err); }
};

const handleStatusChange = async (product, newStatus) => {
    if (!window.confirm(`Are you sure you want to ${newStatus ? 'Activate' : 'Deactivate'} this item?`)) return;
    try {
        const updatedProduct = { ...product, is_active: newStatus };
        await fetchWithAuth(`${import.meta.env.VITE_API_URL}/products/${product._id || product.id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(updatedProduct)
        });
        fetchData();
    } catch (err) {
        console.error("Error updating status:", err);
        alert("Failed to update status");
    }
};

